    // ----- Reset -----
    function resetChat() {
        pdfTextContent = ""; currentPdfName = ""; currentPdfTitle = "";
        if (currentPdfFileUrl) { URL.revokeObjectURL(currentPdfFileUrl); currentPdfFileUrl = null; }
        if (currentPdf2FileUrl) { URL.revokeObjectURL(currentPdf2FileUrl); currentPdf2FileUrl = null; }
        if (currentPdf3FileUrl) { URL.revokeObjectURL(currentPdf3FileUrl); currentPdf3FileUrl = null; }
        pdfNameDisplay.textContent = "Ningún archivo seleccionado";
        pdfStatusDisplay.textContent = "";
        pdfUploadInput.value = null;
        pdf2TextContent = ""; currentPdf2Name = "";
        pdf3TextContent = ""; currentPdf3Name = "";
        conversationHistory = [];
        pdf2NameDisplay.textContent = "Ningún archivo seleccionado";
        pdf2StatusDisplay.textContent = "";
        pdf2UploadInput.value = null;
        pdf2Section.style.display = 'none';
        pdf3NameDisplay.textContent = "Ningún archivo seleccionado";
        pdf3StatusDisplay.textContent = "";
        pdf3UploadInput.value = null;
        pdf3Section.style.display = 'none';
        botAvatarDataUrl = "";
        userAvatarDataUrl = "";
        botAvatarNameDisplay.textContent = "Sin imagen";
        userAvatarNameDisplay.textContent = "Sin imagen";
        botAvatarPreview.classList.remove('visible');
        botAvatarPreview.removeAttribute('src');
        userAvatarPreview.classList.remove('visible');
        userAvatarPreview.removeAttribute('src');
        botAvatarUploadInput.value = null;
        userAvatarUploadInput.value = null;
        chatDisplay.innerHTML = '<div class="system-message">Por favor, carga un PDF para comenzar.</div>';
        questionInput.value = "";
        questionInput.disabled = true;
        sendButton.disabled = true;
        downloadPdfBtn.disabled = true;
        downloadHtmlBtn.disabled = true;
        downloadChatbotBtn.disabled = true;
        if(togglePdfViewerButton1) { togglePdfViewerButton1.disabled = true; togglePdfViewerButton1.textContent = "Ver PDF 1"; }
        if(togglePdfViewerButton2) { togglePdfViewerButton2.disabled = true; togglePdfViewerButton2.textContent = "Ver PDF 2"; }
        if(togglePdfViewerButton3) { togglePdfViewerButton3.disabled = true; togglePdfViewerButton3.textContent = "Ver PDF 3"; }
        if (pdfViewerContainer.classList.contains('visible')) pdfViewerContainer.classList.remove('visible');
        pdfIframe.src = 'about:blank';
        pdfViewerVisible = false;
        currentlyViewingPdf = 0;
    }

    function togglePdfViewer(pdfIndex) {
        let url = null;
        let btn = null;
        if (pdfIndex === 1) { url = currentPdfFileUrl; btn = togglePdfViewerButton1; }
        if (pdfIndex === 2) { url = currentPdf2FileUrl; btn = togglePdfViewerButton2; }
        if (pdfIndex === 3) { url = currentPdf3FileUrl; btn = togglePdfViewerButton3; }
        if (!url || !btn) return;

        if (pdfViewerVisible && currentlyViewingPdf === pdfIndex) {
            pdfViewerContainer.classList.remove('visible');
            btn.textContent = `Ver PDF ${pdfIndex}`;
            pdfViewerVisible = false;
            currentlyViewingPdf = 0;
        } else {
            if(togglePdfViewerButton1) togglePdfViewerButton1.textContent = "Ver PDF 1";
            if(togglePdfViewerButton2) togglePdfViewerButton2.textContent = "Ver PDF 2";
            if(togglePdfViewerButton3) togglePdfViewerButton3.textContent = "Ver PDF 3";
            
            pdfViewerContainer.classList.add('visible');
            pdfIframe.src = url;
            btn.textContent = `Ocultar PDF ${pdfIndex}`;
            pdfViewerVisible = true;
            currentlyViewingPdf = pdfIndex;
        }
    }

    // ----- PDF 1 Upload -----
    function handlePdfUpload(event) {
        const file = event.target.files[0];
        if (!file) return;
        resetChat();
        pdfNameDisplay.textContent = file.name;
        const isValid = file.type === "application/pdf" || file.name.toLowerCase().endsWith(".pdf");
        if (!isValid) {
            pdfStatusDisplay.textContent = `"${file.name}" no es un PDF válido.`;
            pdfStatusDisplay.style.color = "var(--danger-color)";
            return;
        }
        currentPdfName = file.name;
        pdfStatusDisplay.textContent = "Procesando PDF...";
        pdfStatusDisplay.style.color = "var(--warning-color)";
        addMessageToChat("Cargando " + currentPdfName + "...", "system");
        if (currentPdfFileUrl) URL.revokeObjectURL(currentPdfFileUrl);
        currentPdfFileUrl = URL.createObjectURL(file);
        if(togglePdfViewerButton1) togglePdfViewerButton1.disabled = false;
        const reader = new FileReader();
        reader.onload = async (e) => {
            const typedarray = new Uint8Array(e.target.result);
            try {
                const pdf = await pdfjsLib.getDocument({ data: typedarray }).promise;
                let text = "";
                try { const meta = await pdf.getMetadata(); currentPdfTitle = meta?.info?.Title?.trim() || ""; } catch(_) { currentPdfTitle = ""; }
                for (let i = 1; i <= pdf.numPages; i++) {
                    const page = await pdf.getPage(i);
                    const tc = await page.getTextContent();
                    tc.items.forEach(item => text += item.str + " ");
                    text += "\n";
                }
                pdfTextContent = text;
                pdfStatusDisplay.textContent = `"${currentPdfName}" cargado. ¡Listo para preguntar!`;
                pdfStatusDisplay.style.color = "var(--success-color)";
                questionInput.disabled = false;
                sendButton.disabled = false;
                addMessageToChat(`"${currentPdfName}" está listo.`, "system");
                questionInput.focus();
                downloadChatbotBtn.disabled = false;
                pdf2Section.style.display = 'block';
                pdf3Section.style.display = 'block';
            } catch (error) {
                pdfStatusDisplay.textContent = "Error al procesar el PDF.";
                pdfStatusDisplay.style.color = "var(--danger-color)";
                pdfTextContent = "";
                addMessageToChat("Error procesando PDF: " + error.message, "system error");
                if (currentPdfFileUrl) { URL.revokeObjectURL(currentPdfFileUrl); currentPdfFileUrl = null; }
                if(togglePdfViewerButton1) togglePdfViewerButton1.disabled = true;
                pdfUploadInput.value = null;
            }
        };
        reader.readAsArrayBuffer(file);
    }

    // ----- PDF 2 Upload -----
    function handlePdf2Upload(event) {
        const file = event.target.files[0];
        if (!file) return;
        const isValid = file.type === "application/pdf" || file.name.toLowerCase().endsWith(".pdf");
        if (!isValid) {
            pdf2StatusDisplay.textContent = `"${file.name}" no es un PDF válido.`;
            pdf2StatusDisplay.style.color = "var(--danger-color)";
            return;
        }
        currentPdf2Name = file.name;
        pdf2NameDisplay.textContent = file.name;
        pdf2StatusDisplay.textContent = "Procesando segundo PDF...";
        pdf2StatusDisplay.style.color = "var(--warning-color)";
        if (currentPdf2FileUrl) URL.revokeObjectURL(currentPdf2FileUrl);
        currentPdf2FileUrl = URL.createObjectURL(file);
        if(togglePdfViewerButton2) togglePdfViewerButton2.disabled = false;
        const reader = new FileReader();
        reader.onload = async (e) => {
            const typedarray = new Uint8Array(e.target.result);
            try {
                const pdf = await pdfjsLib.getDocument({ data: typedarray }).promise;
                let text = "";
                for (let i = 1; i <= pdf.numPages; i++) {
                    const page = await pdf.getPage(i);
                    const tc = await page.getTextContent();
                    tc.items.forEach(item => text += item.str + " ");
                    text += "\n";
                }
                pdf2TextContent = text;
                pdf2StatusDisplay.textContent = `"${currentPdf2Name}" cargado.`;
                pdf2StatusDisplay.style.color = "var(--success-color)";
                addMessageToChat(`Segundo documento "${currentPdf2Name}" también está listo.`, "system");
                pdf3Section.style.display = 'block';
            } catch (error) {
                pdf2StatusDisplay.textContent = "Error al procesar el segundo PDF.";
                pdf2StatusDisplay.style.color = "var(--danger-color)";
                pdf2TextContent = "";
                if (currentPdf2FileUrl) { URL.revokeObjectURL(currentPdf2FileUrl); currentPdf2FileUrl = null; }
                if(togglePdfViewerButton2) togglePdfViewerButton2.disabled = true;
                pdf2UploadInput.value = null;
            }
        };
        reader.readAsArrayBuffer(file);
    }

